and lib.PERIOD_FLAG =lib1.PERIOD_FLAG
 LEFT JOIN dmcode.cm_guoku_area_code a
 ON lib.AREA_CODE = a.area_no_id
 WHERE lib.DACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m')
