BEGIN

DECLARE V_STEP_ID       INT           DEFAULT 0; 
DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'visual_screen.P_VS_GROWTH_PUBLIC_BUDGET.PRC';
DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    
