UPDATE visual_screen.vs_growth_public_budget SET AREA_DSCR = '石柱县' WHERE AREA_CODE= '500240';
UPDATE visual_screen.vs_growth_public_budget SET AREA_DSCR = '万盛区' WHERE AREA_CODE= '500131';
